package agentdocs

import (
	"encoding/json"
	"runtime"
	"strings"
	"testing"
	"unicode/utf8"
)

func TestCatalogReferencesAreStableAndResolvable(t *testing.T) {
	if err := Validate(); err != nil {
		t.Fatal(err)
	}
	want := []string{"commands", "tasks", "goals", "reviews", "notifications", "jobs", "logs", "configuration", "channels", "harnesses", "instances-primary", "workspace-state", "security", "troubleshooting", "architecture"}
	for _, id := range want {
		if _, ok := topicByID(id); !ok {
			t.Errorf("missing required topic %q", id)
		}
	}
}

func TestTaskAndGoalTopicsDocumentLiveListingCommands(t *testing.T) {
	for _, test := range []struct {
		topic string
		want  []string
	}{
		{topic: "tasks", want: []string{"/tasks", "direct `spynel tasks`", "default to `open`", "three", "review", "failed", "NDJSON", "Telegram", "--detail", "never starts a harness"}},
		{topic: "goals", want: []string{"/goals", "direct `spynel goals`", "default to `open`", "seven", "abandoned", "NDJSON", "WhatsApp", "round", "without invoking a harness"}},
	} {
		document, err := Lookup(Request{Topic: test.topic})
		if err != nil {
			t.Fatal(err)
		}
		output, err := Render(Request{Topic: test.topic})
		if err != nil {
			t.Fatal(err)
		}
		if document.Kind != "topic" {
			t.Fatalf("%s document = %#v", test.topic, document)
		}
		for _, want := range test.want {
			if !strings.Contains(output, want) {
				t.Errorf("%s documentation missing %q:\n%s", test.topic, want, output)
			}
		}
	}
}

func TestHarnessTopicDocumentsPiACPAndQueueBatching(t *testing.T) {
	output, err := Render(Request{Topic: "harnesses"})
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{"`pi`", "ACP aliases", "harness.acp_command", "stdio", "not an endpoint URL", "every agent prefix defaults empty", "such as `/goal`", "dispatched together", "not an operating-system sandbox"} {
		if !strings.Contains(output, want) {
			t.Errorf("harness documentation missing %q:\n%s", want, output)
		}
	}
}

func TestAboutTopicStatesProductBoundaryAndPillars(t *testing.T) {
	output, err := Render(Request{Topic: "workspace-state"})
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{"Simplicity at scale", "classic, non-AI program", "One human → one agent → infinite agents", "assistant-facing relationship", "Three pillars", "communication interface", "Markdown task management", "Agentic loops", "harness supplies intelligence", "Simplicity. Leverage. Quality."} {
		if !strings.Contains(output, want) {
			t.Errorf("about documentation missing %q:\n%s", want, output)
		}
	}
}

func TestIndexTopicAndSearchPagination(t *testing.T) {
	index, err := Lookup(Request{})
	if err != nil {
		t.Fatal(err)
	}
	if index.Kind != "index" || index.Page.Number != 1 || index.Page.Total != 1 || len(index.Topics) != len(topics) {
		t.Fatalf("index = %#v", index)
	}
	topic, _ := Lookup(Request{Topic: "goals"})
	if topic.Kind != "topic" || topic.ID != "goals" || len(topic.Sections) == 0 || topic.Sections[0].ID == "" {
		t.Fatalf("topic = %#v", topic)
	}
	search, _ := Lookup(Request{Search: "review"})
	if search.Kind != "search" || search.Query != "review" || search.Page.TotalEntries < 2 {
		t.Fatalf("search = %#v", search)
	}
	badPage, _ := Lookup(Request{Topic: "goals", Page: 99})
	if badPage.Error == nil || badPage.Error.Code != "page_out_of_range" || !strings.Contains(badPage.Error.Suggestion, "goals page 1") {
		t.Fatalf("bad page = %#v", badPage)
	}
}

func TestPaginationUsesConservativeTokenBudgetAndRecordBoundaries(t *testing.T) {
	weights := []pageWeight{{tokens: <REDACTED> {tokens: <REDACTED> {tokens: <REDACTED> {tokens: <REDACTED>
	start, end, first, ok := paginate(weights, 1)
	if !ok || start != 0 || end != 2 || first.Total != 2 || first.TokenBudget != DefaultTokenBudget || first.EstimatedTokens != 8_000 {
		t.Fatalf("first page = %d:%d %#v, %t", start, end, first, ok)
	}
	start, end, second, ok := paginate(weights, 2)
	if !ok || start != 2 || end != 4 || second.EstimatedTokens != 4_100 {
		t.Fatalf("second page = %d:%d %#v, %t", start, end, second, ok)
	}
	if got := estimateTokens(strings.Repeat("x", 30_000)); got != DefaultTokenBudget {
		t.Fatalf("token estimate = %d", got)
	}
	byteWeights := []pageWeight{{tokens: <REDACTED> bytes: 35_000, runes: 20_000}, {tokens: <REDACTED> bytes: 35_000, runes: 20_000}}
	_, end, metadata, ok := paginate(byteWeights, 1)
	if !ok || end != 1 || metadata.Total != 2 {
		t.Fatalf("byte-bounded page = end %d, %#v, %t", end, metadata, ok)
	}
	escaped := weigh("<plain>")
	if escaped.bytes != len(`\u003cplain\u003e`)+256 || escaped.runes != len(`\u003cplain\u003e`)+256 {
		t.Fatalf("representation-aware weight = %#v", escaped)
	}
}

func TestJSONSchemaErrorsSuggestionsAndOutputBounds(t *testing.T) {
	output, err := Render(Request{Topic: "golas", Format: "json"})
	if err != nil {
		t.Fatal(err)
	}
	var document Document
	if err := json.Unmarshal([]byte(output), &document); err != nil {
		t.Fatal(err)
	}
	if document.SchemaVersion != SchemaVersion || document.Kind != "error" || document.Error == nil || document.Error.Code != "unknown_topic" || document.Error.Suggestion != "spynel docs goals" {
		t.Fatalf("error document = %#v", document)
	}
	for _, request := range []Request{{}, {Topic: "tasks"}, {Search: "state"}, {Topic: strings.Repeat("x", 129)}} {
		for _, format := range []string{"text", "json"} {
			request.Format = format
			output, err := Render(request)
			if err != nil {
				t.Fatalf("Render(%#v): %v", request, err)
			}
			if len(output) > MaxBytes || utf8.RuneCountInString(output) > MaxRunes {
				t.Fatalf("unbounded output: %d bytes, %d runes", len(output), utf8.RuneCountInString(output))
			}
		}
	}
	section, _ := Lookup(Request{Topic: "tasks#lifecycle"})
	if section.ID != "tasks#lifecycle" || len(section.Sections) != 1 || section.Sections[0].ID != "lifecycle" {
		t.Fatalf("section reference = %#v", section)
	}
	badSection, _ := Lookup(Request{Topic: "tasks#lifecycl"})
	if badSection.Error == nil || badSection.Error.Code != "unknown_section" || badSection.Error.Suggestion != "spynel docs tasks#lifecycle" {
		t.Fatalf("section suggestion = %#v", badSection)
	}
	malformed, _ := Lookup(Request{Topic: "tasks#"})
	if malformed.Error == nil || malformed.Error.Code != "invalid_reference" {
		t.Fatalf("malformed section reference = %#v", malformed)
	}
	jsonOutput, err := Render(Request{Topic: "goals", Format: "json"})
	if err != nil {
		t.Fatal(err)
	}
	var sized Document
	if err := json.Unmarshal([]byte(jsonOutput), &sized); err != nil || sized.Page.Bytes != len(jsonOutput) || sized.Page.Runes != utf8.RuneCountInString(jsonOutput) {
		t.Fatalf("JSON size metadata = %#v, actual %d/%d, %v", sized.Page, len(jsonOutput), utf8.RuneCountInString(jsonOutput), err)
	}
}

func TestPlainOutputHasNoTerminalControlsAndPromptPathIsCallable(t *testing.T) {
	output, err := Render(Request{Topic: "commands"})
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(output, "\x1b") || strings.Contains(output, "\r") {
		t.Fatalf("plain output contains terminal controls: %q", output)
	}
	control, err := Render(Request{Search: "review\x1b[31m"})
	if err != nil || strings.Contains(control, "\x1b") || !strings.Contains(control, "invalid_input") {
		t.Fatalf("control query response = %q, %v", control, err)
	}
	guidance := PromptGuidance()
	if !strings.Contains(guidance, " docs <topic>") || !strings.Contains(guidance, "AGENTS.md") || strings.Count(InjectPromptGuidance(PromptPlaceholder+"\n"+PromptPlaceholder), "docs <topic>") != 1 {
		t.Fatalf("prompt guidance = %q", guidance)
	}
	if runtime.GOOS == "windows" && strings.Contains(guidance, `\\`) {
		t.Fatalf("Windows guidance retained escaped path separators: %q", guidance)
	}
	if got := promptCommand(`C:\Program Files\Spynel\spynel.exe`); got != `"C:/Program Files/Spynel/spynel.exe"` {
		t.Fatalf("portable Windows command = %q", got)
	}
}

//go:build linux || darwin

package cli

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/agent0ai/spynel/internal/app"
	"github.com/agent0ai/spynel/internal/config"
	"github.com/agent0ai/spynel/internal/core"
	"github.com/agent0ai/spynel/internal/harness"
	"github.com/agent0ai/spynel/internal/instance"
	"github.com/agent0ai/spynel/internal/orchestrator"
	"github.com/agent0ai/spynel/internal/updater"
	"github.com/agent0ai/spynel/internal/workspace"
)

type workerAgentFixture struct {
	service       *app.Service
	client        *harness.WorkerClient
	owner         *instance.Election
	term          string
	cfg           config.Config
	harnessConfig harness.HarnessConfig
	log           string
	cancel        context.CancelFunc
	done          chan error
}

func newWorkerAgentFixture(t *testing.T, names ...string) *workerAgentFixture {
	t.Helper()
	t.Setenv("XDG_CONFIG_HOME", t.TempDir())
	t.Setenv("HOME", t.TempDir())
	root, err := filepath.EvalSymlinks(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	if err := workspace.Init(root, false); err != nil {
		t.Fatal(err)
	}
	cfg, err := config.Load(config.PathForRoot(root))
	if err != nil {
		t.Fatal(err)
	}
	cfg.Orchestrator.IntervalSec, cfg.Orchestrator.SemanticHeartbeatMinutes = 60, 1
	f := &workerAgentFixture{cfg: cfg, log: filepath.Join(root, "synthetic-methods")}
	t.Setenv("SPYNEL_TEST_WORKER_PROVIDER", "1")
	t.Setenv("SPYNEL_TEST_WORKER_EVIDENCE", f.log)
	executable, _ := os.Executable()
	f.harnessConfig = harness.HarnessConfig{Name: "codex", Command: executable, Cwd: root, Sandbox: "read-only", ApprovalPolicy: "never", SessionsFile: filepath.Join(root, "sessions.json")}
	if len(names) > 0 {
		f.harnessConfig.Name = names[0]
	}
	f.open(t)
	t.Cleanup(func() {
		f.stop(t)
		_, err := f.client.Call(context.Background(), harness.WorkerRequest{Action: "shutdown"})
		if err != nil {
			t.Error(err)
		}
		f.client.Close()
		_ = f.owner.Release(f.term)
		waitWorkerAgent(t, func() bool { _, err := os.Stat(filepath.Dir(f.client.Info().Socket)); return os.IsNotExist(err) })
	})
	return f
}

func (f *workerAgentFixture) open(t *testing.T) {
	t.Helper()
	var err error
	f.owner, err = instance.New(f.cfg.StatePath())
	if err != nil {
		t.Fatal(err)
	}
	f.term, err = f.owner.NewToken()
	if err != nil {
		t.Fatal(err)
	}
	if _, ok, err := f.owner.TryAcquire("127.0.0.1:10001", f.term); err != nil || !ok {
		t.Fatal("owner acquisition", err)
	}
	f.client, err = harness.OpenWorker(t.Context(), f.harnessConfig, f.owner.ID(), f.term)
	if err != nil {
		t.Fatal(err)
	}
	f.service = app.New(f.cfg, harness.NewSupervisor(harness.NewBuiltinRegistry(), f.harnessConfig))
	f.service.Orchestrator.Worker = f.client
	f.service.Orchestrator.SetPrimaryOwned(true)
}

func (f *workerAgentFixture) start(t *testing.T) {
	t.Helper()
	ctx, cancel := context.WithCancel(t.Context())
	f.cancel, f.done = cancel, make(chan error, 1)
	manager := f.service.Orchestrator
	go func() { f.done <- manager.Run(ctx) }()
}

func (f *workerAgentFixture) stop(t *testing.T) {
	t.Helper()
	if f.cancel != nil {
		f.cancel()
		select {
		case <-f.done:
		case <-time.After(5 * time.Second):
			t.Fatal("manager did not detach")
		}
		f.cancel = nil
	}
	f.service.Orchestrator.Wait()
	if err := f.service.Close(); err != nil {
		t.Error(err)
	}
}

func waitWorkerAgent(t *testing.T, predicate func() bool) {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for !predicate() {
		if time.Now().After(deadline) {
			t.Fatal("background worker assertion timed out")
		}
		time.Sleep(10 * time.Millisecond)
	}
}

func (f *workerAgentFixture) inspect(t *testing.T) []harness.WorkerExecution {
	t.Helper()
	reply, err := f.client.Call(t.Context(), harness.WorkerRequest{Action: "inspect"})
	if err != nil {
		t.Fatal(err)
	}
	return reply.Executions
}

func (f *workerAgentFixture) trigger(t *testing.T, want bool) {
	t.Helper()
	var started bool
	var err error
	waitWorkerAgent(t, func() bool {
		started, err = f.service.Orchestrator.TriggerSemanticHeartbeat(t.Context())
		return err == nil || !strings.Contains(err.Error(), "scheduler is unavailable")
	})
	if err != nil || started != want {
		t.Fatalf("manual heartbeat = %v, %v; want %v", started, err, want)
	}
}

func TestWorkerAgentManagerRestoresHeartbeatJobAndFixedDelay(t *testing.T) {
	f := newWorkerAgentFixture(t)
	var delivery harness.WorkerDelivery
	reached := make(chan struct{})
	var once sync.Once
	f.service.Orchestrator.JobDelivery = func(id int, event harness.WorkerDelivery) error {
		if err := f.service.Runtime.RecordJobDelivery(id, event); err != nil {
			return err
		}
		once.Do(func() { delivery = event; close(reached) })
		return errors.New("synthetic lost controller after archive sync")
	}
	f.start(t)
	f.trigger(t, true)
	select {
	case <-reached:
	case <-time.After(10 * time.Second):
		t.Fatal("ordinary agent failed actual admission")
	}
	first := f.inspect(t)[0]
	if first.Agent == nil || len(first.Agent.ID) < 8 || first.Agent.Deadline.Sub(first.Agent.StartedAt) != 5*time.Minute {
		t.Fatal("ordinary agent descriptor/deadline invalid")
	}
	jobs := f.service.Runtime.Jobs()
	if len(jobs) != 1 {
		t.Fatalf("jobs = %d", len(jobs))
	}
	job := jobs[0]
	if job.Kind != "heartbeat" || job.WorkID != first.Agent.ID || job.ProviderIterations != 1 {
		t.Fatal("background job identity/accounting changed")
	}
	f.trigger(t, false)
	f.stop(t)
	identity := f.client.Info()
	obsolete := f.client
	defer obsolete.Close()
	if err := f.owner.Release(f.term); err != nil {
		t.Fatal(err)
	}
	f.open(t)
	if f.client.Info().PID != identity.PID || f.client.Info().Process.StartTime != identity.Process.StartTime || f.client.Info().Process.Generation != identity.Process.Generation || updater.VerifyProcess(identity.Process) != nil {
		t.Fatal("replacement changed worker identity")
	}
	t.Logf("retained ordinary worker pid=%d start=%s generation=%s", identity.PID, identity.Process.StartTime, identity.Process.Generation)
	if _, err := obsolete.Call(t.Context(), harness.WorkerRequest{Action: "interrupt", Key: first.Key}); err == nil {
		t.Fatal("obsolete controller retained control")
	}
	admit := f.service.Orchestrator.JobStarted
	f.service.Orchestrator.JobStarted = func(orchestrator.Lease, string, time.Time, int, int) (int, error) {
		return 0, errors.New("synthetic job admission failure")
	}
	if err := f.service.Orchestrator.ScanOnce(t.Context()); err != nil {
		t.Fatal(err)
	}
	f.service.Orchestrator.Wait()
	if f.inspect(t)[0].CommittedCursor != 0 {
		t.Fatal("failed admission consumed events")
	}
	f.service.Orchestrator.JobStarted = admit
	f.start(t)
	waitWorkerAgent(t, func() bool {
		current := f.inspect(t)
		return len(current) == 1 && current[0].CommittedCursor >= delivery.Cursor
	})
	current := f.inspect(t)[0]
	if *current.Agent != *first.Agent {
		t.Fatal("attachment reset ordinary agent lifetime")
	}
	jobs = f.service.Runtime.Jobs()
	if len(jobs) != 1 || jobs[0].Number != job.Number || jobs[0].StableID != job.StableID || jobs[0].Generation != job.Generation {
		t.Fatal("attachment allocated another job")
	}
	f.trigger(t, false)
	for i := 0; i < 3; i++ {
		if err := f.service.Orchestrator.ScanOnce(t.Context()); err != nil {
			t.Fatal(err)
		}
	}
	releasedAt := time.Now()
	if _, err := f.client.Call(t.Context(), harness.WorkerRequest{Action: "interrupt", Key: first.Key}); err != nil {
		t.Fatal(err)
	}
	waitWorkerAgent(t, func() bool {
		return len(f.inspect(t)) == 0 && len(f.service.Runtime.Jobs()) == 0 && f.service.Orchestrator.WorkStatus().HeartbeatState == "scheduled"
	})
	next := f.service.Orchestrator.WorkStatus().NextHeartbeatAt
	if next.Before(releasedAt.Add(time.Minute)) || next.After(time.Now().Add(time.Minute)) {
		t.Fatal("fixed delay was not measured from terminal release")
	}
	data, err := os.ReadFile(f.log)
	if err != nil || strings.Count(string(data), "turn/start\n") != 1 {
		t.Fatal("attachment sent another provider turn", err)
	}
	_, output, err := f.service.Runtime.ArchivedJob(job.Number)
	if err != nil || delivery.Event.Text != "" && strings.Count(output, delivery.Event.Text) != 1 {
		t.Fatal("archive replay duplicated output", err)
	}
}

// Drop exactly the Send reply at a private Unix proxy. The accepted case
// forwards first; the rejected case proves no provider admission happened.
func dropWorkerReply(t *testing.T, socket, action string, accepted, inspectionUnavailable bool) func() {
	t.Helper()
	target := socket + ".target"
	if err := os.Rename(socket, target); err != nil {
		t.Fatal(err)
	}
	listener, err := net.Listen("unix", socket)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(socket, 0600); err != nil {
		t.Fatal(err)
	}
	transport := &http.Transport{DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
		return (&net.Dialer{}).DialContext(ctx, "unix", target)
	}}
	var applied atomic.Bool
	server := &http.Server{Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			return
		}
		var request harness.WorkerRequest
		if json.Unmarshal(body, &request) != nil {
			return
		}
		if request.Action == action && !accepted || request.Action == "inspect" && inspectionUnavailable && applied.Load() {
			connection, _, _ := w.(http.Hijacker).Hijack()
			_ = connection.Close()
			return
		}
		upstream, _ := http.NewRequestWithContext(r.Context(), http.MethodPost, "http://worker/worker", bytes.NewReader(body))
		upstream.Header = r.Header.Clone()
		response, err := transport.RoundTrip(upstream)
		if err != nil {
			http.Error(w, "synthetic proxy failure", 502)
			return
		}
		defer response.Body.Close()
		if request.Action == action {
			_, _ = io.Copy(io.Discard, response.Body)
			applied.Store(true)
			connection, _, _ := w.(http.Hijacker).Hijack()
			_ = connection.Close()
			return
		}
		w.WriteHeader(response.StatusCode)
		_, _ = io.Copy(w, response.Body)
	})}
	done := make(chan struct{})
	go func() { defer close(done); _ = server.Serve(listener) }()
	var once sync.Once
	restore := func() {
		once.Do(func() {
			_ = server.Close()
			<-done
			transport.CloseIdleConnections()
			_ = os.Remove(socket)
			if err := os.Rename(target, socket); err != nil {
				t.Error(err)
			}
		})
	}
	t.Cleanup(restore)
	return restore
}

func TestWorkerAgentAmbiguousSendReconcilesSameJob(t *testing.T) {
	for _, accepted := range []bool{false, true} {
		name := "not-admitted"
		if accepted {
			name = "admitted-reply-lost"
		}
		t.Run(name, func(t *testing.T) {
			f := newWorkerAgentFixture(t)
			f.client.Close()
			restore := dropWorkerReply(t, f.client.Info().Socket, "send", accepted, false)
			f.start(t)
			f.trigger(t, true)
			waitWorkerAgent(t, func() bool {
				jobs := f.service.Runtime.Jobs()
				return len(jobs) == 1 && jobs[0].Execution == app.JobDegraded
			})
			job := f.service.Runtime.Jobs()[0]
			restore()
			f.client.Close()
			if err := f.service.Orchestrator.ScanOnce(t.Context()); err != nil {
				t.Fatal(err)
			}
			if accepted {
				waitWorkerAgent(t, func() bool { current := f.inspect(t); return len(current) == 1 && current[0].CommittedCursor > 0 })
				jobs := f.service.Runtime.Jobs()
				if len(jobs) != 1 || jobs[0].StableID != job.StableID {
					t.Fatal("ambiguous send duplicated job")
				}
				f.trigger(t, false)
				if _, err := f.client.Call(t.Context(), harness.WorkerRequest{Action: "interrupt", Key: f.inspect(t)[0].Key}); err != nil {
					t.Fatal(err)
				}
			}
			waitWorkerAgent(t, func() bool { return len(f.service.Runtime.Jobs()) == 0 && len(f.inspect(t)) == 0 })
			data, _ := os.ReadFile(f.log)
			want := 0
			if accepted {
				want = 1
			}
			if strings.Count(string(data), "turn/start\n") != want {
				t.Fatal("ambiguous send repeated provider admission")
			}
		})
	}
}

func TestWorkerAgentNotificationAttachmentKeepsIndependentIdentity(t *testing.T) {
	f := newWorkerAgentFixture(t)
	file := f.cfg.StatePath("tasks", "done", "synthetic.md")
	if err := orchestrator.WriteDocument(file, orchestrator.Document{FrontMatter: map[string]any{"id": "synthetic-task", "status": "done"}}); err != nil {
		t.Fatal(err)
	}
	id, err := core.NewSourceMessageID()
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC()
	agent := &harness.WorkerAgent{ID: id, Kind: "notification", File: file, StartedAt: now, Deadline: now.Add(time.Minute)}
	if _, err := f.client.Call(t.Context(), harness.WorkerRequest{Action: "send", Sequence: 1, Key: "orchestrator:notification:synthetic", Prompt: "synthetic notification", Agent: agent}); err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	if err := f.service.Orchestrator.ScanOnce(ctx); err != nil {
		t.Fatal(err)
	}
	waitWorkerAgent(t, func() bool { return len(f.service.Runtime.Jobs()) == 1 })
	job := f.service.Runtime.Jobs()[0]
	if job.Kind != "notification" || job.WorkID != id || job.ProviderIterations != 1 {
		t.Fatal("notification inherited task identity")
	}
	if _, err := f.client.Call(t.Context(), harness.WorkerRequest{Action: "interrupt", Key: f.inspect(t)[0].Key}); err != nil {
		t.Fatal(err)
	}
	waitWorkerAgent(t, func() bool { return len(f.inspect(t)) == 0 && len(f.service.Runtime.Jobs()) == 0 })
}

func TestWorkerAgentHeartbeatRecoversAfterScheduledInspectionOutage(t *testing.T) {
	f := newWorkerAgentFixture(t)
	identity := f.client.Info()
	// Keep this isolated owner fresh through the real one-minute timer.
	renewCtx, renewCancel := context.WithCancel(t.Context())
	renewDone := make(chan struct{})
	renewErrors := make(chan error, 1)
	go func() {
		defer close(renewDone)
		ticker := time.NewTicker(time.Second)
		defer ticker.Stop()
		for {
			select {
			case <-renewCtx.Done():
				return
			case <-ticker.C:
				if _, ok, err := f.owner.Renew(f.term); err != nil || !ok {
					if err == nil {
						err = errors.New("isolated renewal lost ownership")
					}
					select {
					case renewErrors <- err:
					default:
					}
					return
				}
			}
		}
	}()
	t.Cleanup(func() { renewCancel(); <-renewDone })
	f.start(t)
	waitWorkerAgent(t, func() bool { return !f.service.Orchestrator.WorkStatus().NextHeartbeatAt.IsZero() })
	selected := f.service.Orchestrator.WorkStatus().NextHeartbeatAt
	socket := identity.Socket
	hidden := socket + ".scheduled-outage"
	if err := os.Rename(socket, hidden); err != nil {
		t.Fatal(err)
	}
	f.client.Close()
	var restoreOnce sync.Once
	restore := func() {
		restoreOnce.Do(func() {
			if err := os.Rename(hidden, socket); err != nil {
				t.Error(err)
			}
			f.client.Close()
		})
	}
	t.Cleanup(restore)
	t.Logf("natural scheduled heartbeat deadline=%s; native worker pid=%d start=%s", selected.Format(time.RFC3339Nano), identity.PID, identity.Process.StartTime)
	if _, err := f.client.Call(t.Context(), harness.WorkerRequest{Action: "inspect"}); err == nil {
		t.Fatal("endpoint outage was not injected")
	}
	select {
	case <-t.Context().Done():
		t.Fatal(t.Context().Err())
	case err := <-renewErrors:
		t.Fatal("isolated election renewal failed", err)
	case <-time.After(time.Until(selected.Add(1500 * time.Millisecond))):
	}
	restore()
	current := f.inspect(t)
	if len(current) != 0 {
		t.Fatal("outage unexpectedly admitted a heartbeat")
	}
	if err := updater.VerifyProcess(identity.Process); err != nil {
		t.Fatal("worker identity changed", err)
	}
	restoredAt := time.Now()
	waitWorkerAgent(t, func() bool {
		return f.service.Orchestrator.WorkStatus().NextHeartbeatAt.After(selected)
	})
	select {
	case err := <-renewErrors:
		t.Fatal("isolated election renewal failed", err)
	default:
	}
	after := f.service.Orchestrator.WorkStatus()
	if !after.NextHeartbeatAt.After(selected) || after.NextHeartbeatAt.Before(restoredAt.Add(time.Minute-time.Second)) || len(f.inspect(t)) != 0 {
		t.Fatalf("natural heartbeat timer never recovered after authenticated endpoint restoration: deadline before=%s after=%s state=%s; no provider admission", selected.Format(time.RFC3339Nano), after.NextHeartbeatAt.Format(time.RFC3339Nano), after.HeartbeatState)
	}
	f.trigger(t, true)
	waitWorkerAgent(t, func() bool { return len(f.inspect(t)) == 1 })
	current = f.inspect(t)
	if _, err := f.client.Call(t.Context(), harness.WorkerRequest{Action: "interrupt", Key: current[0].Key}); err != nil {
		t.Fatal(err)
	}
	waitWorkerAgent(t, func() bool { return len(f.inspect(t)) == 0 && len(f.service.Runtime.Jobs()) == 0 })
	data, err := os.ReadFile(f.log)
	if err != nil || strings.Count(string(data), "turn/start\n") != 1 {
		t.Fatal("recovery duplicated provider admission", err)
	}
	t.Logf("recovered fixed-delay deadline=%s; unchanged native generation=%s", after.NextHeartbeatAt.Format(time.RFC3339Nano), identity.Process.Generation)
}

