	}
	entries, _, _ := s.History.Entries("cli", "storage")
	if len(entries) != 2 || len(entries[1].Covers) != 1 || entries[1].ExecutionID != "execution" {
		t.Fatal("retry lost coverage or duplicated history")
	}
}

